use knownext_recording::{RecordingService,model::{Settings,Session,Status}};
use serde_json::{json,Value};
use std::fs;
#[test]
fn read_only_settings_preserve_original_and_verified_copy_without_acknowledging_recovery(){
    let temp=tempfile::tempdir().unwrap();let path=temp.path().join("settings.json");let original=b"{broken-owned-settings";fs::write(&path,original).unwrap();let service=RecordingService::new(temp.path().into()).unwrap();let snapshot=service.request("snapshot",Value::Null).unwrap();let permissions=fs::metadata(&path).unwrap().permissions();let mut readonly=permissions.clone();readonly.set_readonly(true);fs::set_permissions(&path,readonly).unwrap();let result=service.request("recover-settings",json!({"revision":snapshot["settingsRecoveryRevision"]}));fs::set_permissions(&path,permissions).unwrap();assert!(result.is_err());assert_eq!(fs::read(&path).unwrap(),original);let copies=fs::read_dir(temp.path().join("settings-recovery")).unwrap().map(|entry|fs::read(entry.unwrap().path()).unwrap()).collect::<Vec<_>>();assert_eq!(copies,vec![original.to_vec()]);assert!(service.request("snapshot",Value::Null).unwrap()["settingsError"].is_string());
}
#[test]
fn bad_settings_block_capture_and_require_reviewed_recovery_with_an_exact_copy(){
    let temp=tempfile::tempdir().unwrap();let file=temp.path().join("settings.json");let original=br#"{"schemaVersion":99,"private":"owned-settings-sentinel"}"#;fs::write(&file,original).unwrap();let service=RecordingService::new(temp.path().into()).unwrap();let snapshot=service.request("snapshot",Value::Null).unwrap();assert!(snapshot["settingsError"].is_string());let revision=snapshot["settingsRecoveryRevision"].as_str().unwrap();assert!(service.request("settings",serde_json::to_value(Settings::default()).unwrap()).is_err());assert!(service.request("start",json!({"settings":Settings::default()})).is_err());assert!(service.request("recover-settings",json!({"revision":"stale"})).is_err());assert_eq!(fs::read(&file).unwrap(),original);let result=service.request("recover-settings",json!({"revision":revision})).unwrap();assert!(result["settingsError"].is_null());assert_eq!(result["settings"]["startWithWindows"],false);assert!(result["captureOwner"].is_null());let copies=fs::read_dir(temp.path().join("settings-recovery")).unwrap().map(|entry|fs::read(entry.unwrap().path()).unwrap()).collect::<Vec<_>>();assert_eq!(copies,vec![original.to_vec()]);let current=fs::read(&file).unwrap();assert!(service.request("recover-settings",json!({"revision":revision})).is_err());assert_eq!(fs::read(&file).unwrap(),current);
}
#[test]
fn reopening_preserves_odd_pcm_and_original_manifest_then_archives_before_first_change(){
    let temp=tempfile::tempdir().unwrap();let session=Session::new(Settings::default(),None);let id=session.id.clone();let folder=temp.path().join(&id);fs::create_dir(&folder).unwrap();let original=serde_json::to_vec(&session).unwrap();fs::write(folder.join("session.json"),&original).unwrap();let pcm=[1,0,255];fs::write(folder.join("microphone.pcm"),pcm).unwrap();let service=RecordingService::new(temp.path().into()).unwrap();let snapshot=service.request("snapshot",Value::Null).unwrap();assert_eq!(snapshot["sessions"][0]["status"],"attention");assert_eq!(snapshot["sessions"][0]["samples"],1);assert_eq!(fs::read(folder.join("microphone.pcm")).unwrap(),pcm);assert_eq!(fs::read(folder.join("session.json")).unwrap(),original);service.request("keep",json!({"id":id,"keep":true})).unwrap();let copies=fs::read_dir(temp.path().join("sessions-recovery")).unwrap().map(|entry|fs::read(entry.unwrap().path()).unwrap()).collect::<Vec<_>>();assert_eq!(copies,vec![original]);let mut changed:Value=serde_json::from_slice(&fs::read(folder.join("session.json")).unwrap()).unwrap();changed["schemaVersion"]=json!(99);let changed=serde_json::to_vec(&changed).unwrap();fs::write(folder.join("session.json"),&changed).unwrap();assert!(service.request("delete-audio",json!({"id":id})).is_err());assert_eq!(fs::read(folder.join("session.json")).unwrap(),changed);assert_eq!(fs::read(folder.join("microphone.pcm")).unwrap(),pcm);
}
#[test]
fn completed_metadata_is_not_rewritten_and_future_sessions_are_reported_without_audio_cleanup(){
    let temp=tempfile::tempdir().unwrap();let mut known=Session::new(Settings::default(),None);known.status=Status::Completed;known.keep=true;let mut future=Session::new(Settings::default(),None);future.keep=true;for session in [&known,&future]{fs::create_dir(temp.path().join(&session.id)).unwrap();}let known_raw=serde_json::to_vec(&known).unwrap();let mut future_value=serde_json::to_value(&future).unwrap();future_value["schemaVersion"]=json!(9);let future_raw=serde_json::to_vec(&future_value).unwrap();fs::write(temp.path().join(&known.id).join("session.json"),&known_raw).unwrap();let future_folder=temp.path().join(&future.id);fs::write(future_folder.join("session.json"),&future_raw).unwrap();fs::write(future_folder.join("microphone.pcm"),b"owned-audio").unwrap();let service=RecordingService::new(temp.path().into()).unwrap();let snapshot=service.request("snapshot",Value::Null).unwrap();assert_eq!(snapshot["sessions"].as_array().unwrap().len(),1);assert_eq!(snapshot["unavailableSessions"],1);assert_eq!(fs::read(temp.path().join(&known.id).join("session.json")).unwrap(),known_raw);assert_eq!(fs::read(future_folder.join("session.json")).unwrap(),future_raw);assert_eq!(fs::read(future_folder.join("microphone.pcm")).unwrap(),b"owned-audio");
}
